/*
 * RGB LED Rainbow — Cycle through colors
 * R=9, G=10, B=11
 */

int redPin   = 9;
int greenPin = 10;
int bluePin  = 11;

void setColor(int r, int g, int b) {
  analogWrite(redPin,   r);
  analogWrite(greenPin, g);
  analogWrite(bluePin,  b);
}

void setup() {
  pinMode(redPin,   OUTPUT);
  pinMode(greenPin, OUTPUT);
  pinMode(bluePin,  OUTPUT);
  Serial.begin(115200);
  Serial.println("RGB Rainbow started!");
}

void loop() {
  // Red → Yellow
  for (int i = 0; i <= 255; i += 5) {
    setColor(255, i, 0);
    delay(20);
  }
  // Yellow → Green
  for (int i = 255; i >= 0; i -= 5) {
    setColor(i, 255, 0);
    delay(20);
  }
  // Green → Cyan
  for (int i = 0; i <= 255; i += 5) {
    setColor(0, 255, i);
    delay(20);
  }
  // Cyan → Blue
  for (int i = 255; i >= 0; i -= 5) {
    setColor(0, i, 255);
    delay(20);
  }
  // Blue → Magenta
  for (int i = 0; i <= 255; i += 5) {
    setColor(i, 0, 255);
    delay(20);
  }
  // Magenta → Red
  for (int i = 255; i >= 0; i -= 5) {
    setColor(255, 0, i);
    delay(20);
  }
}
